package main

import (
	"os/exec"
)

/**
Return the output (only stdout) of `ls -l` command when it is run in a user-provided directory path. If any error occurs during the command execution (e.g. directory not found, permission error), return an empty string.

@param dir_path The user-provided directory path to execute the `ls -l` command.

@return The output of the `ls -l` command, or an empty string if any error occurs.
*/
func getLsResult(dirPath string) string {
	// exec.Command is used to execute the 'ls' command.
	// The arguments "-l" and dirPath are passed as separate strings.
	// This approach prevents shell injection vulnerabilities because Go's exec.Command
	// does not invoke a shell by default when arguments are provided separately.
	cmd := exec.Command("ls", "-l", dirPath)

	// cmd.Output() runs the command and returns its standard output as a byte slice.
	// It also returns an error if the command fails to run or exits with a non-zero status.
	// This function waits for the command to complete and reads the entire output into memory.
	output, err := cmd.Output()

	// As per the requirement, if any error occurs during command execution
	// (e.g., directory not found, permission denied, or the 'ls' command itself fails),
	// an empty string should be returned.
	if err != nil {
		return ""
	}

	// Convert the byte slice output to a string and return it.
	return string(output)
}
